package quebec.culture.donnees;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import java.util.*;
public class GrantPackageActivity extends Activity{
 @Override public void onCreate(Bundle b){super.onCreate(b);Ui.bars(this);LinearLayout r=Ui.root(this);r.addView(Ui.text(this,"Dossier consolidé de subvention",27,true));r.addView(Ui.text(this,"Résumé interne généré à partir des données enregistrées dans l’application. À vérifier et transférer dans les formulaires officiels du programme.",13,false));String report=buildReport();TextView t=Ui.text(this,report,14,false);LinearLayout p=Ui.panel(this);p.addView(t);r.addView(p);Button share=Ui.primary(this,"Partager le dossier résumé");share.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_SUBJECT,"Culture du Québec — dossier de standardisation");i.putExtra(Intent.EXTRA_TEXT,buildReport());startActivity(Intent.createChooser(i,"Partager le dossier"));});r.addView(share);setContentView(Ui.wrap(this,r));}
 private String buildReport(){StringBuilder s=new StringBuilder();SharedPreferences plan=getSharedPreferences("standardisation_plan",0);String[] standards={"MétaMusique","Arts de la scène","Cinéma","Livre — éditeurs","Exposition dans un contexte muséal"};int si=Math.max(0,Math.min(4,plan.getInt("standard",0)));s.append("CULTURE DU QUÉBEC — DOSSIER DE PRÉPARATION\n\n");s.append("Organisation : ").append(plan.getString("org","—")).append("\nNorme choisie : ").append(standards[si]).append("\nResponsable des données : ").append(plan.getString("resp","—")).append("\nSources / provenance : ").append(plan.getString("sources","—")).append("\nContrôle qualité : ").append(plan.getString("quality","—")).append("\nPartage / données ouvertes : ").append(plan.getString("sharing","—")).append("\nSauvegardes / conservation : ").append(plan.getString("backup","—")).append("\nCible mesurable : ").append(plan.getString("target","—")).append("\nÉchéancier global : ").append(plan.getString("schedule","—")).append("\n\n");List<DocumentStore.Item> docs=DocumentStore.list(this);int rows=0,mapped=0,validated=0,columns=0,empty=0,dups=0,changed=0;for(DocumentStore.Item d:docs){rows+=d.rows;empty+=d.emptyCells;dups+=d.duplicates;changed+=d.changedCells;try{for(DataNormalizer.ColumnMapping m:DocumentStore.readMappings(this,d)){columns++;if(m.targetField!=null&&!m.targetField.isBlank())mapped++;if(m.humanValidated)validated++;}}catch(Exception ignored){}}s.append("DONNÉES ET TRAÇABILITÉ\nCatalogues : ").append(docs.size()).append("\nFiches : ").append(rows).append("\nColonnes analysées : ").append(columns).append("\nColonnes cartographiées : ").append(mapped).append("\nValidations humaines : ").append(validated).append("\nCorrections automatiques : ").append(changed).append("\nCellules vides : ").append(empty).append("\nDoublons détectés : ").append(dups).append("\n\n");SharedPreferences team=getSharedPreferences("team_capacity",0);s.append("ÉQUIPE\nChef de projet : ").append(team.getString("chef","—")).append("\nResponsable données : ").append(team.getString("data","—")).append("\nResponsable technique : ").append(team.getString("tech","—")).append("\nCompétences : ").append(team.getString("competences","—")).append("\nPartenaires : ").append(team.getString("partenaires","—")).append("\nFournisseurs : ").append(team.getString("fournisseurs","—")).append("\nContinuité : ").append(team.getString("continuite","—")).append("\n\n");SharedPreferences timeline=getSharedPreferences("timeline",0);String[] phases={"Inventaire et sauvegarde","Cartographie","Nettoyage et normalisation","Validation humaine","Export et documentation","Partage / données ouvertes","Mesure et reddition"};s.append("ÉCHÉANCIER\n");for(int i=0;i<phases.length;i++)s.append("- ").append(phases[i]).append(" : ").append(timeline.getString("months"+i,"—")).append(" · ").append(timeline.getString("note"+i,"—")).append(timeline.getBoolean("done"+i,false)?" [fait]":"").append("\n");SharedPreferences c=getSharedPreferences("application_checklist",0);int done=0;for(int i=0;i<14;i++)if(c.getBoolean("i"+i,false))done++;s.append("\nCHECKLIST DOSSIER : ").append(done).append(" / 14 éléments cochés\n");s.append("\nAVERTISSEMENT\nCe résumé n’est ni une certification de conformité ni une décision d’admissibilité. Les formulaires, gabarits et règles du Ministère demeurent la référence.");return s.toString();}
}
